# pylint: disable=C0301,W0613
"""
coverage test for autocell, deployed on jn-cell08
mode: routine commit local
trigger by jenkins
"""

import os
import sys
import logging

# 配置日志
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

MODE = os.environ.get("MODE", "routine")


class BaseCoverageJob:
    """Coverage 任务基类"""

    def __init__(self, mode):
        self.mode = mode

    def execute(self):
        """执行 coverage 任务"""
        raise NotImplementedError("子类必须实现 execute 方法")

    def validate(self):
        """验证环境配置"""
        logger.info(f"Validating environment for mode: {self.mode}")
        return True


class BaseSummaryJob:
    """Summary 任务基类"""

    def __init__(self, mode):
        self.mode = mode

    def generate_summary(self):
        """生成 summary 报告"""
        raise NotImplementedError("子类必须实现 generate_summary 方法")

    def validate(self):
        """验证环境配置"""
        logger.info(f"Validating environment for summary mode: {self.mode}")
        return True


class RoutineCoverageJob(BaseCoverageJob):
    """Routine 模式的 Coverage 任务"""

    def __init__(self):
        super().__init__("routine")

    def execute(self):
        logger.info("Executing routine coverage")
        print("routine coverage")
        return True


class CommitCoverageJob(BaseCoverageJob):
    """Commit 模式的 Coverage 任务"""

    def __init__(self):
        super().__init__("commit")

    def execute(self):
        logger.info("Executing commit coverage")
        print("commit coverage")
        return True


class LocalCoverageJob(BaseCoverageJob):
    """Local 模式的 Coverage 任务"""

    def __init__(self):
        super().__init__("local")

    def execute(self):
        logger.info("Executing local coverage")
        print("local coverage")
        return True


class RoutineSummaryJob(BaseSummaryJob):
    """Routine 模式的 Summary 任务"""

    def __init__(self):
        super().__init__("routine")

    def generate_summary(self):
        logger.info("Generating routine summary")
        return True


class CommitSummaryJob(BaseSummaryJob):
    """Commit 模式的 Summary 任务"""

    def __init__(self):
        super().__init__("commit")

    def generate_summary(self):
        logger.info("Generating commit summary")
        return True


class LocalSummaryJob(BaseSummaryJob):
    """Local 模式的 Summary 任务"""

    def __init__(self):
        super().__init__("local")

    def generate_summary(self):
        logger.info("Generating local summary")
        return True


def get_coverage_job(mode):
    """根据 mode 获取对应的 CoverageJob 实例"""
    job_map = {
        "routine": RoutineCoverageJob,
        "commit": CommitCoverageJob,
        "local": LocalCoverageJob
    }

    if mode not in job_map:
        logger.error(f"Unknown mode: {mode}")
        return None

    return job_map[mode]()


def get_summary_job(mode):
    """根据 mode 获取对应的 SummaryJob 实例"""
    job_map = {
        "routine": RoutineSummaryJob,
        "commit": CommitSummaryJob,
        "local": LocalSummaryJob
    }

    if mode not in job_map:
        logger.error(f"Unknown mode: {mode}")
        return None

    return job_map[mode]()


def main():
    """主入口函数，保持向后兼容"""
    logger.info(f"Starting coverage with MODE: {MODE}")

    # 获取并执行 coverage job
    coverage_job = get_coverage_job(MODE)
    if coverage_job is None:
        logger.error("Failed to create coverage job")
        print("unknown mode")
        sys.exit(1)

    if not coverage_job.validate():
        logger.error("Coverage job validation failed")
        sys.exit(1)

    coverage_job.execute()

    # 获取并执行 summary job
    summary_job = get_summary_job(MODE)
    if summary_job is None:
        logger.error("Failed to create summary job")
        sys.exit(1)

    if not summary_job.validate():
        logger.error("Summary job validation failed")
        sys.exit(1)

    summary_job.generate_summary()

    logger.info("Coverage completed successfully")


if __name__ == "__main__":
    main()
"
